  getTransaction(input: Record<string, unknown>): Promise<unknown>;
  getBudget(input: Record<string, unknown>): Promise<unknown>;
  listBudgetAllocations(input: Record<string, unknown>): Promise<unknown>;
  listObligations(input: Record<string, unknown>): Promise<unknown>;
