const mapAccount = (row: Row, asOf: string) => ({ id: String(row.id), name: String(row.name), type: String(row.type), bankName: String(row.bank_name || ""), currency: String(row.currency || "DOP"), openingBalanceMinor: Number(row.opening_balance_minor || 0), openingBalanceDate: String(row.opening_balance_date), balanceMinor: Number(row.balance_minor || 0), archived: bool(row.archived), createdAt: nullableString(row.created_at), updatedAt: nullableString(row.updated_at), asOfDate: asOf });
const mapCategory = (row: Row) => ({ id: String(row.id), name: String(row.name), kind: String(row.kind || "expense"), color: String(row.color || "#2463eb"), transactionCount: Number(row.transaction_count || 0), budgetCount: Number(row.budget_count || 0), obligationCount: Number(row.obligation_count || 0), goalCount: Number(row.goal_count || 0) });
const mapTransaction = (row: Row) => { const type = String(row.type); const amountMinor = Number(row.amount_minor || 0); const feeMinor = Number(row.fee_minor || 0); return { id: String(row.id), type, accountId: String(row.account_id), accountName: nullableString(row.account_name), accountBankName: nullableString(row.account_bank_name), destinationAccountId: nullableString(row.destination_account_id), destinationAccountName: nullableString(row.destination_account_name), destinationBankName: nullableString(row.destination_bank_name), amountMinor, feeMinor, totalDebitMinor: type === "expense" || type === "transfer" ? amountMinor + feeMinor : 0, transferMode: nullableString(row.transfer_mode), paymentMethod: String(row.payment_method || "standard"), counterpartyBank: String(row.counterparty_bank || ""), feeCategoryId: nullableString(row.fee_category_id), feeCategoryName: nullableString(row.fee_category_name), categoryId: nullableString(row.category_id), categoryName: nullableString(row.category_name), occurredOn: String(row.occurred_on), status: String(row.status), voidedAt: nullableString(row.voided_at), description: String(row.description || ""), taskId: nullableString(row.task_id), taskTitle: nullableString(row.task_title), projectId: nullableString(row.project_id), projectName: nullableString(row.project_name), obligationOccurrenceId: nullableString(row.obligation_occurrence_id), obligationId: nullableString(row.obligation_id), obligationTitle: nullableString(row.obligation_title), goalId: nullableString(row.goal_id), goalTitle: nullableString(row.goal_title), reservationConsumedMinor: Number(row.reservation_consumed_minor || 0), reservationMonth: String(row.reservation_month || ""), goalReservationConsumedMinor: Number(row.goal_reservation_consumed_minor || 0), createdAt: nullableString(row.created_at), updatedAt: nullableString(row.updated_at), sourceDirection: type === "income" ? "credit" : type === "expense" || type === "transfer" ? "debit" : "adjustment" }; };
const mapObligation = (row: Row) => ({ id: String(row.id), title: String(row.title), concept: String(row.concept || row.title), kind: String(row.kind), expectedAmountMinor: Number(row.expected_amount_minor || 0), reservedMinor: Number(row.reserved_minor || 0), accountId: nullableString(row.account_id), accountName: nullableString(row.account_name), categoryId: nullableString(row.category_id), categoryName: nullableString(row.category_name), frequency: String(row.frequency || "monthly"), coveredByBudget: bool(row.covered_by_budget), reserveMonth: String(row.reserve_month || ""), nextDueDate: String(row.next_due_date), active: bool(row.active), createdAt: nullableString(row.created_at), updatedAt: nullableString(row.updated_at) });
const mapOccurrence = (row: Row) => ({ id: String(row.id), obligationId: String(row.obligation_id), obligationTitle: nullableString(row.obligation_title), dueDate: String(row.due_date), expectedMinor: Number(row.expected_minor || 0), paidMinor: Number(row.paid_minor || 0), remainingMinor: Math.max(0, Number(row.expected_minor || 0) - Number(row.paid_minor || 0)), status: String(row.status), transactionId: nullableString(row.transaction_id), createdAt: nullableString(row.created_at), updatedAt: nullableString(row.updated_at) });
